## 2. Unit tests (Vitest)

Install (when you’re ready to implement):

```bash
npm install -D vitest typescript @types/node
```

`src/reverseString.test.ts`:

```typescript
import { describe, it, expect } from "vitest";
import { reverseString } from "./reverseString";

describe("reverseString", () => {
  it("reverses a simple ASCII string", () => {
    expect(reverseString("hello")).toBe("olleh");
  });

  it("returns empty string for empty input", () => {
    expect(reverseString("")).toBe("");
  });

  it("handles single character", () => {
    expect(reverseString("a")).toBe("a");
  });

  it("handles palindromes", () => {
    expect(reverseString("racecar")).toBe("racecar");
  });

  it("preserves Unicode characters (emoji)", () => {
    expect(reverseString("hello 👋")).toBe("👋 olleh");
  });

  it("preserves spaces and punctuation", () => {
    expect(reverseString("a b!")).toBe("!b a");
  });
});
```

Add to `package.json`:

```json
{
  "scripts": {
    "test": "vitest run",
    "test:watch": "vitest"
  }
}
```

Optional `vitest.config.ts`:

```typescript
import { defineConfig } from "vitest/config";

export default defineConfig({
  test: {
    globals: false,
  },
});
```

